import{_ as i,o as a,c as o,a2 as l}from"./chunks/framework.CgxQ0r6v.js";const g=JSON.parse('{"title":"Unidad Curricular: Proyecto Socio Tecnológico III","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_III/Contenido_Programatico.md","filePath":"materias/Proyecto_Sociotecnologico_III/Contenido_Programatico.md"}'),r={name:"materias/Proyecto_Sociotecnologico_III/Contenido_Programatico.md"};function t(n,e,s,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="unidad-curricular-proyecto-socio-tecnologico-iii" tabindex="-1">Unidad Curricular: Proyecto Socio Tecnológico III <a class="header-anchor" href="#unidad-curricular-proyecto-socio-tecnologico-iii" aria-label="Permalink to &quot;Unidad Curricular: Proyecto Socio Tecnológico III&quot;">​</a></h1><p><strong>Trayecto:</strong> III <strong>Código:</strong> PTP339 <strong>Unidades Crédito:</strong> 9 <strong>Duración:</strong> 3 trimestres <strong>Tipo:</strong> Proyecto</p><table tabindex="0"><thead><tr><th style="text-align:left;">Densidad Semanal</th><th style="text-align:left;">Hora Acad.</th><th style="text-align:left;">HTEA</th><th style="text-align:left;">HTEI</th><th style="text-align:left;">THTE</th></tr></thead><tbody><tr><td style="text-align:left;">60&#39;</td><td style="text-align:left;">6</td><td style="text-align:left;">0.5</td><td style="text-align:left;">6.5</td><td style="text-align:left;">6.5</td></tr></tbody></table><hr><h2 id="saberes-contenido-analitico" tabindex="-1">SABERES (Contenido Analítico) <a class="header-anchor" href="#saberes-contenido-analitico" aria-label="Permalink to &quot;SABERES (Contenido Analítico)&quot;">​</a></h2><p><strong>Unidad 1: Problema o situación que requiera desarrollo de aplicaciones informáticas</strong></p><ul><li>Diagnóstico Participativo</li><li>Fases del Diagnóstico Participativo <ul><li>Determinar los Requerimientos</li><li>Clasificación de los Requisitos (funcionales y no funcionales)</li><li>Elaborar el Plan Diagnóstico</li><li>Levantar información</li><li>Procesamiento de la Información (Cuantificación de datos)</li><li>Socialización de los Resultados</li></ul></li></ul><p><strong>Unidad 2: Planteamiento del proyecto</strong></p><ul><li>Definición del problema, objetivos y alcance</li><li>Factores de Riesgo y de éxito del proyecto</li></ul><p><strong>Unidad 3: Planificación de Proyectos</strong></p><ul><li>Estudio de Factibilidad</li><li>Cronograma de actividades</li></ul><p><strong>Unidad 4: Ejecución del Proyecto Sociotecnológico</strong></p><ul><li>Aplicación de la metodología seleccionada.</li><li>Diseño y desarrollo de la aplicación informática</li></ul><p><strong>Unidad 5: Implantación</strong></p><ul><li>Plan de implantación</li></ul><p><strong>Unidad 6: Pruebas</strong></p><ul><li>Planificación y aplicación de las pruebas</li><li>Plan de optimización</li><li>Corrección de errores críticos</li></ul><p><strong>Unidad 7: Manuales de usuarios y de sistemas e informe final</strong></p><ul><li>Desarrollo de los manuales requeridos en el proyecto y entrenamiento a usuarios.</li></ul><hr><h2 id="estrategias" tabindex="-1">ESTRATEGIAS <a class="header-anchor" href="#estrategias" aria-label="Permalink to &quot;ESTRATEGIAS&quot;">​</a></h2><ul><li>Los actores deben abordar la comunidad para conocerla, describirla y detectar necesidades.</li><li>Realizar talleres, conversatorios o charlas con invitados especiales de organismos que apoyen la ejecución de proyectos.</li><li>Se recomienda que se continúe con el uso de las metodologías del enfoque del marco lógico para el abordaje comunitario.</li><li>Investigar sobre los proyectos informáticos locales, regionales y nacionales y los organismos que apoyan la ejecución de los mismos.</li><li>Planificar las actividades del proyecto sociotecnológico.</li><li>Plantear alternativas de soluciones ante situaciones y problemas reales, relacionados con soluciones informáticas.</li><li>Seleccionar y justificar la Metodología de desarrollo de software a utilizar en el proyecto sociotecnológico.</li><li>Discutir acerca de Metodologías de Desarrollo de Software: <ul><li>Metodologías Tradicionales Vs Ágiles.</li><li>Visión general de las distintas metodologías de desarrollo de software (RUP, WATCH, MERINDE, XP, SCRUM, otras).</li><li>Productos entregables de un proyecto de desarrollo de software.</li></ul></li></ul><hr><h2 id="recursos" tabindex="-1">RECURSOS <a class="header-anchor" href="#recursos" aria-label="Permalink to &quot;RECURSOS&quot;">​</a></h2><ul><li>Pizarra magnética</li><li>Marcadores</li><li>Material Educativo Computarizado: Material Instructivo, Software</li><li>Computador</li><li>Proyector Multimedia</li><li>Plataforma Tecnológica</li><li>Aula de encuentros, aula taller, laboratorios.</li></ul><hr><h2 id="evaluacion" tabindex="-1">EVALUACIÓN <a class="header-anchor" href="#evaluacion" aria-label="Permalink to &quot;EVALUACIÓN&quot;">​</a></h2><p>Entrega y presentación del Informe: indicándose las actividades y fases desarrolladas. Coevaluación y Autoevaluación.</p><p><strong>Productos Entregables:</strong></p><ul><li><strong>1er Informe de avances:</strong><ul><li>Documento de Requisito.</li><li>Propuesta de solución.</li><li>Metodología seleccionada.</li><li>Planificación del proyecto.</li><li>Factores de riesgo.</li><li>Estudio de Factibilidad.</li><li>Cálculo de Costo.</li><li>Informe de Visitas a la comunidad.</li></ul></li><li><strong>2do Informe de avance (Afinar):</strong><ul><li>Entrega y presentación del proyecto sociotecnológico final.</li><li>Manuales de Usuarios y de sistema.</li><li>Informe de Visitas a la comunidad.</li></ul></li></ul><hr><h2 id="referencias" tabindex="-1">REFERENCIAS <a class="header-anchor" href="#referencias" aria-label="Permalink to &quot;REFERENCIAS&quot;">​</a></h2><ul><li>Ortegón E., Pacheco, J., Prieto, A., (2005). Metodología del Marco Lógico para la Planificación, el Seguimiento y la Evaluación de Proyectos y Programas. Chile.</li><li>Crespo M., (2009). Guía de Desarrollo de Proyectos Sociales Comunitarios Bajo el Enfoque del Marco Lógico. Caracas – Venezuela.</li><li>Kendall &amp; Kendall (2005). Análisis y diseño de sistemas. (6ª ed.). México: Pearson.</li><li>Laudon, K. &amp; Laudon, J. (2004). Sistemas de información gerencial. (8ª ed.). México: Prentice Hall.</li><li>Pressman, R. (2002). Ingeniería de software. Un enfoque práctico. (5ª ed.). España: McGraw-Hill Interamericana de España, S.A.</li><li>Senn, J. (1987). Análisis y Diseño de Sistemas de Información. México: McGraw Hill.</li><li>Sommerville, L. (2006). Ingeniería de Software. (8ª ed.). México: Pearson.</li><li>Pérez D., Ginesta G., Matías M., (2007). Ingeniería del Software en entornos de SL. Barcelona.</li><li>Ruble, D. (1998). Análisis y Diseño Práctico de Sistemas. México: Prentice Hall.</li><li>Yourdon, E. (1993). Análisis Estructurado Moderno. (1ª ed.). México: Prentice Hall.</li><li>Peralta M. Sistema de Información. Documento en línea. Disponible en: <a href="http://www.monografias.com/trabajos7/sisinf/" target="_blank" rel="noreferrer">http://www.monografias.com/trabajos7/sisinf/</a></li><li>Leopoldo C (2008). Introducción a los Sistemas de Información (2008). Documento en línea. Disponible en: <a href="http://techtastico.com/post/introduccion-a-los-sistemas-de-informacion/" target="_blank" rel="noreferrer">http://techtastico.com/post/introduccion-a-los-sistemas-de-informacion/</a></li><li>Erich Gamma, Richard Helm (2002). Pearson Education.</li><li>Humphrey Watts S. (2001). Introducción al Proceso Software Personal. Addison Wesley. Meyer.</li><li>María Paloma Diaz (2005). Ingeniería de Software y patrones de Diseño. Pearson Education.</li><li>McConnell. (1999). Desarrollo y Gestión de Proyectos Informáticos. McGraw Hill; Madrid.</li><li>O’Brien, James. (2003). Sistemas de información gerencial. Cuarta Edición. Irwin-McGraw Hill. Colombia.</li><li>Pfleeger, Shari Lawrence (2002). Ingeniería de Software. Teoría y Práctica. Pearson Education, Buenos Aires.</li><li>Reifer, Donald J. (1993). SOFTWARE MANAGEMENT. IEEE Computer Society Press. Los Alamitos, CA.</li><li>Wang, Yingxu &amp; King, Graham (2000). Software Engineering Processes. Principles and Applications. CRC Press LLC, N. W. Florida.</li><li>Eckois, Steve (1986). Como diseñar y Desarrollar Sistemas de Información. 1a. Ed. Venezuela.</li><li>Gomez, Guillermo. (1998). Sistemas Administrativos. 1a. Ed. México.</li><li>Sampieri, Roberto y otros. Metodología de la Investigación. Ed. McGraw-hill, 1996.</li></ul>',33)])])}const p=i(r,[["render",t]]);export{g as __pageData,p as default};
